import{test}from'node:test';import assert from'node:assert/strict';import{readFileSync}from'node:fs';import{verifyWordUseLanguageReview,readBeforeWordUseLanguageReview}from'./check-word-use-language-review-20261101.mjs';
const folder='docs/word-use-language-review-20261101/';
void test('language release is bound to all reviewed questions, correct active audio and actual full recovery readback',()=>{const r=verifyWordUseLanguageReview();assert(r.publicationApproved&&r.appearanceUnchanged);assert.notDeepEqual(readBeforeWordUseLanguageReview('data/klink-word-use.json',r),readFileSync('data/klink-word-use.json'));});
void test('language release rejects missing approval, missing spelling or speech review, bad backup and altered audio',()=>{
 for(const[file,edit]of[['docs/klink-owner-release-word-use-language-review-20261101.json',r=>{r.publicationApproved=false;}],[folder+'spelling-check.json',r=>{r.unresolved.push('unreviewed');}],[folder+'speech-review.json',r=>{r.reviewCompleted=false;}],[folder+'backup.json',r=>{r.fullReadback=false;}],[folder+'backup.json',r=>{r.parts[0].verified=false;}]])assert.throws(()=>verifyWordUseLanguageReview(f=>{if(f!==file)return readFileSync(f);const r=JSON.parse(readFileSync(f));edit(r);return Buffer.from(JSON.stringify(r));}),file);
 const audio=JSON.parse(readFileSync(folder+'audio.json')).find(c=>!c.reused);for(const file of['data/klink-word-use.json','data/klink-word-use-audio.json','public'+audio.src])assert.throws(()=>verifyWordUseLanguageReview(f=>f===file?Buffer.concat([readFileSync(f),Buffer.from('changed')]):readFileSync(f)),file);
});
